// Build the product spec from the Trigger input (no hardcoded 'edit this line').
const scenario = ($json.scenario || 'use_and_file');
const base = {
  product_code: 'PRD-2026-T18', product_name: 'iSecure Term Shield',
  category: 'pre_approved', product_type: 'term', lock_in_years: 0,
  charge_spread_ok: true, nav_disclosure_daily: true,
  premium_band_inr: [12000, 90000], riders: ['accidental_death', 'critical_illness'],
  target_segment: 'salaried_25_45'
};
const variants = {
  use_and_file: {},
  file_and_use: { product_code: 'PRD-2026-U07', product_name: 'WealthMax ULIP Edge', category: 'new_category', product_type: 'ulip', lock_in_years: 5 },
  rework: { product_code: 'PRD-2026-U08', product_name: 'QuickGain ULIP', category: 'new_category', product_type: 'ulip', lock_in_years: 3, charge_spread_ok: false }
};
[Object.assign({}, base, variants[scenario] || {}, { scenario })]

// Real work: derive rule_violations and carry the whole spec forward.
const p = $input.first() || {};
const violations = [];
if (p.product_type === 'ulip' && (p.lock_in_years || 0) < 5) violations.push('ULIP lock-in below mandatory 5 years');
if (p.charge_spread_ok === false) violations.push('Charges not spread evenly across lock-in (IRDAI ULIP norms)');
if (p.product_type === 'ulip' && p.nav_disclosure_daily === false) violations.push('Daily NAV disclosure missing');
[Object.assign({}, p, { rule_violations: violations })]

// Two trivial synchronous checks belong in ONE node — no artificial split + merge.
// Carries the spec forward so no downstream 'marker' flags are needed to re-identify it.
const p = $input.first() || {};
const pricing = { mortality_table: 'IALM 2012-14', margin_pct: 12, margin_ok: true,
  sample_annual_premium_inr: p.product_type === 'term' ? 14500 : 96000 };
const compliance = { mandatory_clauses_ok: true, benefit_illustration_ok: true, grievance_clause_ok: true };
[Object.assign({}, p, pricing, { compliance })]

// Combine the two merged branches by INTRINSIC fields (no marker flags):
//   - the deterministic branch is the item that has margin_pct (from Assess)
//   - the LLM branch is the item that has `output` (from Product Summary)
const items = $input.all();
const spec = items.find(i => i && i.margin_pct !== undefined) || {};
const sum = items.find(i => i && i.output) || {};
const summary = sum.output || {};
const route = (spec.rule_violations || []).length ? 'rework'
  : (spec.category === 'pre_approved' ? 'use_and_file' : 'file_and_use');
[{
  product_code: spec.product_code, product_name: spec.product_name,
  category: spec.category, product_type: spec.product_type,
  rule_violations: spec.rule_violations || [],
  filing_route: route,
  margin_pct: spec.margin_pct,
  sample_annual_premium_inr: spec.sample_annual_premium_inr,
  checklist_ok: !!(spec.compliance && spec.compliance.mandatory_clauses_ok),
  product_summary: summary.summary || '',
  key_risks: summary.key_risks || []
}]

const p = $input.first() || {};
const packet = Object.assign({}, p, { action: 'launch_product', disposition: 'launched_use_and_file' });
[{ json_body: JSON.stringify(packet) }]

const r = $input.first() || {};
const p = r.body || {};
const packet = Object.assign({}, p, { action: 'post_launch_filing', launch_ref: 'LNCH-' + (p.id || 101) });
[{ json_body: JSON.stringify(packet) }]

const r = $input.first() || {};
const p = r.body || {};
[{ product_code: p.product_code, product_name: p.product_name, disposition: 'live_use_and_file',
   launch_ref: p.launch_ref, irdai_filing_ref: 'UF-' + (p.id || 101), live_at: new Date().toISOString() }]

// lyzr.llm passes input through and adds `output`, so the memo + the verdict fields
// are both on this item. Strip the transient `output` cleanly instead of setting it undefined.
const p = $input.first() || {};
const memo = (p.output || {}).memo || '';
const packet = Object.assign({}, p, { action: 'file_and_use_submission', filing_memo: memo, actuary_remarks: p.actuary_remarks || '' });
delete packet.output;
[{ json_body: JSON.stringify(packet) }]

const r = $input.first() || {};
const p = r.body || {};
[{ product_code: p.product_code, product_name: p.product_name, disposition: 'filed_awaiting_irdai',
   filing_ref: 'FU-' + (p.id || 101), filed_at: new Date().toISOString() }]

const p = $input.first() || {};
const notice = (p.output || {}).notice || '';
const reason = (p.rule_violations || []).length ? p.rule_violations.join('; ')
  : (p.rework_note || 'Returned by appointed actuary');
[{ product_code: p.product_code, product_name: p.product_name, disposition: 'returned_for_rework',
   rework_reason: reason, rework_notice: notice, returned_at: new Date().toISOString() }]
